{
  "title": "迷雾之森的秘密",
  "scene": "你站在一片古老森林的入口，四周弥漫着浓厚的雾气。不远处，一棵巨大的古树下站着一个神秘的老人，他似乎在等待着什么。老人的身后有一条小径，通向森林深处。你记得村里的传说，这里隐藏着一个被诅咒的宝藏。老人突然开口说：‘年轻人，森林里充满了危险，但如果你能找到宝藏，它将改变你的一生。’",
  "goal": "找到被诅咒的宝藏",
  "clue": "老人的话暗示了宝藏的重要性和危险性",
  "choices": [
    {
      "id": "A",
      "text": "直接沿着小径前进",
      "outcome": "你沿着小径深入森林，雾气越来越浓，但最终你发现了宝藏的所在地。然而，宝藏周围布满了机关，你不得不小心翼翼地行动，最终成功取到了宝藏，但也受了一些轻伤。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "先与老人交谈",
      "outcome": "你走上前与老人交谈，他告诉你了一些关于森林的秘密和宝藏的线索。原来宝藏被一只守护兽保护，但老人给了你一个可以驱散迷雾的水晶。你凭借这些信息顺利找到了宝藏，没有遇到什么危险。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "在周围探索一番",
      "outcome": "你在森林入口附近探索，希望能找到一些有用的信息，但雾气太浓，你什么也没有发现，反而浪费了很多时间。当你再次回到古树下时，老人已经不见了，你只能重新尝试。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
